{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2179-05-18 00:05:00",
      "speaker": "Doctor",
      "text": "Mr. ___, we’ve admitted you today because you’re getting your liver transplant. You’ve been on the list for a while, and a donor has become available."
    },
    {
      "turn_number": 2,
      "time": "2179-05-18 00:06:30",
      "speaker": "Patient",
      "text": "Okay, doc. I’m ready. I’ve been waiting for this. How soon will it happen?"
    },
    {
      "turn_number": 3,
      "time": "2179-05-18 00:07:15",
      "speaker": "Doctor",
      "text": "The surgery is scheduled for this morning. We’ll take you to the OR around noon. You’ll be under general anesthesia, and the team will replace your liver with the donor’s."
    },
    {
      "turn_number": 4,
      "time": "2179-05-18 00:08:00",
      "speaker": "Patient",
      "text": "And my pulmonary hypertension? I’m still on Remodulin. Will that be okay during surgery?"
    },
    {
      "turn_number": 5,
      "time": "2179-05-18 00:09:20",
      "speaker": "Doctor",
      "text": "Yes, we’ll keep your Remodulin running throughout. We’ll also use nitric oxide during the surgery to help keep your pulmonary pressures low and stable."
    },
    {
      "turn_number": 6,
      "time": "2179-05-18 00:10:10",
      "speaker": "Patient",
      "text": "Good. I’m nervous, but I trust you. What about recovery after?"
    },
    {
      "turn_number": 7,
      "time": "2179-05-18 00:11:00",
      "speaker": "Doctor",
      "text": "You’ll go to the ICU after. We’ll monitor your new liver closely—check blood flow, liver enzymes, and how you’re tolerating the transplant. You’ll be on a ventilator at first, but we hope to take you off soon."
    },
    {
      "turn_number": 8,
      "time": "2179-05-18 12:00:00",
      "speaker": "Doctor",
      "text": "Just updating you—we’ve completed the liver transplant. It went smoothly. The new liver is in, and blood flow looks good so far."
    },
    {
      "turn_number": 9,
      "time": "2179-05-18 18:35:00",
      "speaker": "Doctor",
      "text": "We did an ultrasound of your liver this evening. The hepatic artery and portal vein are both open and flowing well. There’s some expected swelling, but nothing concerning."
    },
    {
      "turn_number": 10,
      "time": "2179-05-18 18:36:30",
      "speaker": "Patient",
      "text": "That’s a relief. My breathing feels a bit heavy though. Is that normal?"
    },
    {
      "turn_number": 11,
      "time": "2179-05-18 18:38:00",
      "speaker": "Doctor",
      "text": "Yes, you’re still on the ventilator, and we see some atelectasis—collapsed lung areas—on the X-ray. We’re suctioning and adjusting your settings to help expand your lungs."
    },
    {
      "turn_number": 12,
      "time": "2179-05-19 05:00:00",
      "speaker": "Doctor",
      "text": "Good news—your liver enzymes are starting to come down. That’s a sign the new liver is functioning. We’re also seeing improvement in your chest X-ray."
    },
    {
      "turn_number": 13,
      "time": "2179-05-19 05:02:00",
      "speaker": "Patient",
      "text": "That’s great. When can I breathe on my own?"
    },
    {
      "turn_number": 14,
      "time": "2179-05-19 05:03:30",
      "speaker": "Doctor",
      "text": "We’ll try to wean you off the ventilator tomorrow. Your pressures are stable, and we’ve started sildenafil to help with your pulmonary hypertension instead of nitric oxide."
    },
    {
      "turn_number": 15,
      "time": "2179-05-20 06:00:00",
      "speaker": "Doctor",
      "text": "You’re off the nitric oxide, and your PA pressures are still under 40. That’s excellent. We’ll keep you on sildenafil three times a day."
    },
    {
      "turn_number": 16,
      "time": "2179-05-20 06:02:00",
      "speaker": "Patient",
      "text": "I feel better already. Any sign of rejection?"
    },
    {
      "turn_number": 17,
      "time": "2179-05-20 06:04:00",
      "speaker": "Doctor",
      "text": "Not yet. We’re monitoring your tacrolimus levels daily and adjusting your immunosuppressants. So far, no signs of rejection."
    },
    {
      "turn_number": 18,
      "time": "2179-05-21 07:00:00",
      "speaker": "Doctor",
      "text": "You’ve been extubated and are breathing on your own. Swan-Ganz catheter has been removed. You’re doing well."
    },
    {
      "turn_number": 19,
      "time": "2179-05-21 07:02:00",
      "speaker": "Patient",
      "text": "I’m so glad. Can I sit up now?"
    },
    {
      "turn_number": 20,
      "time": "2179-05-21 07:03:30",
      "speaker": "Doctor",
      "text": "Yes, and we’ll start physical therapy soon. Your drain output is high, so we’re giving albumin to help with fluid balance."
    },
    {
      "turn_number": 21,
      "time": "2179-05-22 08:00:00",
      "speaker": "Doctor",
      "text": "We placed a new central line today to help with medications and monitoring. Your kidney function is a bit off—we’re watching it closely."
    },
    {
      "turn_number": 22,
      "time": "2179-05-22 08:02:00",
      "speaker": "Patient",
      "text": "Is that from the surgery or my old kidneys?"
    },
    {
      "turn_number": 23,
      "time": "2179-05-22 08:04:00",
      "speaker": "Doctor",
      "text": "Likely a mix. We’ve reduced Valcyte because it can affect kidneys. We expect it to improve."
    },
    {
      "turn_number": 24,
      "time": "2179-05-23 09:00:00",
      "speaker": "Doctor",
      "text": "Your labs are trending well—creatinine is down, liver enzymes continue to improve. You’re moving to the regular floor today."
    },
    {
      "turn_number": 25,
      "time": "2179-05-23 09:02:00",
      "speaker": "Patient",
      "text": "That’s great. I feel stronger. Any more tests coming up?"
    },
    {
      "turn_number": 26,
      "time": "2179-05-23 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep doing daily labs. The team is happy with your progress so far."
    },
    {
      "turn_number": 27,
      "time": "2179-05-24 10:00:00",
      "speaker": "Doctor",
      "text": "Still stable. Your Remodulin dose was slightly reduced to 42 ng/kg/min. You’re tolerating it well."
    },
    {
      "turn_number": 28,
      "time": "2179-05-24 10:01:30",
      "speaker": "Patient",
      "text": "Any reason for the change?"
    },
    {
      "turn_number": 29,
      "time": "2179-05-24 10:03:00",
      "speaker": "Doctor",
      "text": "Your pulmonary pressures are stable, so we’re cautiously reducing it. We’ll keep monitoring."
    },
    {
      "turn_number": 30,
      "time": "2179-05-25 11:00:00",
      "speaker": "Doctor",
      "text": "Urine culture shows minimal growth—nothing to treat. You remain afebrile and stable."
    },
    {
      "turn_number": 31,
      "time": "2179-05-26 06:30:00",
      "speaker": "Doctor",
      "text": "We did another liver ultrasound this morning. We’re seeing gas in the liver—especially the left lobe—and some signs of possible infarction."
    },
    {
      "turn_number": 32,
      "time": "2179-05-26 06:32:00",
      "speaker": "Patient",
      "text": "Gas? In my liver? That sounds bad."
    },
    {
      "turn_number": 33,
      "time": "2179-05-26 06:34:00",
      "speaker": "Doctor",
      "text": "It is concerning. It could mean an infection or poor blood flow. We’re ordering a CT scan to get a better look."
    },
    {
      "turn_number": 34,
      "time": "2179-05-26 08:15:00",
      "speaker": "Doctor",
      "text": "The CT shows multiple infarcts in the left lobe and some in the right. There’s air in the liver, which suggests a gas-forming infection."
    },
    {
      "turn_number": 35,
      "time": "2179-05-26 08:17:00",
      "speaker": "Patient",
      "text": "Infection? But I haven’t had a fever."
    },
    {
      "turn_number": 36,
      "time": "2179-05-26 08:19:00",
      "speaker": "Doctor",
      "text": "Immunosuppressants can mask symptoms. We’ve started broad-spectrum antibiotics and are preparing for surgery."
    },
    {
      "turn_number": 37,
      "time": "2179-05-26 09:00:00",
      "speaker": "Doctor",
      "text": "Your heart rate and breathing are increasing. We’re moving you to the ICU."
    },
    {
      "turn_number": 38,
      "time": "2179-05-26 10:05:00",
      "speaker": "Doctor",
      "text": "We’ve intubated you because your oxygen levels dropped. We’re giving pressors to support your blood pressure."
    },
    {
      "turn_number": 39,
      "time": "2179-05-26 11:45:00",
      "speaker": "Doctor",
      "text": "Blood cultures are back. They show E. coli. It’s likely the infection came from the donor liver."
    },
    {
      "turn_number": 40,
      "time": "2179-05-26 11:47:00",
      "speaker": "Patient",
      "text": "So the transplant… it’s infected?"
    },
    {
      "turn_number": 41,
      "time": "2179-05-26 11:49:00",
      "speaker": "Doctor",
      "text": "It appears so. We’re taking you to surgery to remove the infected tissue and check the blood vessels."
    },
    {
      "turn_number": 42,
      "time": "2179-05-26 12:05:00",
      "speaker": "Doctor",
      "text": "Post-op update: we found a large abscess with gas. We couldn’t drain it fully, but we removed necrotic tissue and checked the hepatic artery."
    },
    {
      "turn_number": 43,
      "time": "2179-05-26 12:07:00",
      "speaker": "Patient",
      "text": "Is the liver still working?"
    },
    {
      "turn_number": 44,
      "time": "2179-05-26 12:09:00",
      "speaker": "Doctor",
      "text": "Unfortunately, the damage is severe. Your liver enzymes are very high, and your kidneys are failing. We’ve started CVVH."
    },
    {
      "turn_number": 45,
      "time": "2179-05-26 13:00:00",
      "speaker": "Doctor",
      "text": "We’ve spoken with your health care proxy. Given how sick you are, we’re shifting to comfort care only."
    },
    {
      "turn_number": 46,
      "time": "2179-05-26 13:02:00",
      "speaker": "Patient",
      "text": "So… no more fighting?"
    },
    {
      "turn_number": 47,
      "time": "2179-05-26 13:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep you comfortable. You’re not alone. We’re here with you."
    },
    {
      "turn_number": 48,
      "time": "2179-05-26 14:00:00",
      "speaker": "Doctor",
      "text": "Your blood pressure is dropping despite four pressors. Your organs are shutting down."
    },
    {
      "turn_number": 49,
      "time": "2179-05-26 14:02:00",
      "speaker": "Patient",
      "text": "I’m tired… just let me go."
    },
    {
      "turn_number": 50,
      "time": "2179-05-26 14:04:00",
      "speaker": "Doctor",
      "text": "We’re with you. You’re safe. We’ll keep you pain-free."
    },
    {
      "turn_number": 51,
      "time": "2179-05-26 15:00:00",
      "speaker": "Doctor",
      "text": "Mr. ___, I’m sorry. Despite everything, your body couldn’t recover. You passed peacefully."
    },
    {
      "turn_number": 52,
      "time": "2179-05-26 15:02:00",
      "speaker": "Doctor",
      "text": "We believe the E. coli came from the donor, who had a history of IV drug use. It seeded the liver before transplant."
    },
    {
      "turn_number": 53,
      "time": "2179-05-26 16:00:00",
      "speaker": "Doctor",
      "text": "We’ll inform your family and begin the process of notifying the transplant network about the donor."
    },
    {
      "turn_number": 54,
      "time": "2179-05-26 17:00:00",
      "speaker": "Doctor",
      "text": "The cultures from the liver tissue confirmed E. coli, matching the blood results. It was a multi-drug resistant strain."
    },
    {
      "turn_number": 55,
      "time": "2179-05-26 18:00:00",
      "speaker": "Doctor",
      "text": "We’re documenting everything for the medical review board. This was an unexpected complication."
    },
    {
      "turn_number": 56,
      "time": "2179-05-26 19:00:00",
      "speaker": "Doctor",
      "text": "Your care team is grieving with your family. You were a strong patient, and we did everything we could."
    },
    {
      "turn_number": 57,
      "time": "2179-05-26 20:00:00",
      "speaker": "Doctor",
      "text": "We’ll keep monitoring for any public health implications due to the resistant E. coli."
    },
    {
      "turn_number": 58,
      "time": "2179-05-26 21:00:00",
      "speaker": "Doctor",
      "text": "The hospital chaplain has spoken with your proxy. They’re arranging next steps."
    },
    {
      "turn_number": 59,
      "time": "2179-05-26 22:00:00",
      "speaker": "Doctor",
      "text": "We’ve completed the post-mortem documentation. Your case will be reviewed to improve future transplant safety."
    },
    {
      "turn_number": 60,
      "time": "2179-05-27 00:00:00",
      "speaker": "Doctor",
      "text": "Mr. ___, thank you for your courage. You faced this with dignity. We’ll remember you."
    }
  ],
  "summary": {
    "admission_start": "2179-05-18 00:04:00",
    "admission_end": "2179-05-27 09:43:00",
    "summary_paragraph": "Mr. ___ was admitted for a deceased donor liver transplant due to HCV cirrhosis and decompensated liver disease. The transplant was performed successfully on 2179-05-18, and initial recovery was stable with improving liver function and weaning from nitric oxide to sildenafil for portopulmonary hypertension. By postoperative day 8, he acutely decompensated with tachycardia and respiratory failure. Imaging revealed hepatic infarcts and gas-forming abscesses. Blood and tissue cultures confirmed E. coli bacteremia, likely seeded from the donor liver. Despite surgical debridement and intensive support, he developed multi-organ failure and septic shock. After discussion with his health care proxy, care was transitioned to comfort measures, and he expired on 2179-05-26.",
    "problems": [
      "Unspecified viral hepatitis C without hepatic coma",
      "Acute kidney failure with lesion of tubular necrosis",
      "Septicemia due to escherichia coli [E. coli]",
      "Acute respiratory failure",
      "Acute and subacute necrosis of liver",
      "Hepatic infarction",
      "Severe sepsis",
      "Septic shock",
      "Portal hypertension",
      "Cirrhosis of liver without mention of alcohol",
      "Other chronic pulmonary heart diseases",
      "Complications of transplanted liver",
      "Hepatopulmonary syndrome",
      "Do not resuscitate status",
      "Encounter for palliative care"
    ]
  }
}
